from collections import Counter

def main():
    counts = Counter({'Россия': 0, 'Иностранные': 0})
    try:
        with open('компоненты.csv', newline='', encoding='utf-8') as f:
            reader = csv.reader(f)
            for row in reader:
                if len(row) < 3:
                    continue
                country = row[2].strip()
                if not country:
                    continue
                if country == 'Россия':
                    counts['Россия'] += 1
                else:
                    counts['Иностранные'] += 1
    except FileNotFoundError:
        print('Файл компоненты.csv не найден')
        return

    russia = counts['Россия']
    foreign = counts['Иностранные']
    total = russia + foreign
    share = round((foreign / total) * 100) if total else 0

    print(f'Россия — {russia}')
    print(f'Иностранные — {foreign}')
    print(f'Доля иностранных — {share}%')

if __name__ == '__main__':
    main()
